using TMPro;

public class GameManager : MonoBehaviour
{
    // Lives the player starts with
    [SerializeField] private int startingLives = 3;
    // The text on screen that shows the lives
    [SerializeField] private TMP_Text livesText;

    // Lives left right now
    private int lives;
    // True once the game has ended
    private bool isGameOver;

    void Start()
    {
        lives = startingLives;
        isGameOver = false;
        UpdateLivesText();
    }

    // Other scripts call this when the player is hit
    public void LoseLife()
    {
        // If the game is already over, do nothing
        if (isGameOver)
        {
            return;
        }

        lives = lives - 1;
        UpdateLivesText();

        if (lives <= 0)
        {
            GameOver();
        }
    }

    // Copies the number of lives onto the screen
    private void UpdateLivesText()
    {
        livesText.text = "Lives: " + lives;
    }

    // Ends the game. For now it only writes to the Console
    private void GameOver()
    {
        isGameOver = true;
        Debug.Log("Game over");
    }
}

